<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'), baseline=ref('centered'), selected=ref(0), state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const alpha=computed(()=>dataset.value==='zero'?[0,0,0,0,0,0]:dataset.value==='A'?[20,28,25,39,33,46]:[26,19,35,28,43,36])
const beta=computed(()=>dataset.value==='zero'?[0,0,0,0,0,0]:dataset.value==='A'?[15,20,16,22,23,28]:[16,17,20,20,29,28])
const totals=computed(()=>alpha.value.map((v,i)=>v+beta.value[i]))
const lower=computed(()=>totals.value.map(v=>baseline.value==='centered'?-v/2:0))
const middle=computed(()=>alpha.value.map((v,i)=>lower.value[i]+v))
const upper=computed(()=>totals.value.map((v,i)=>lower.value[i]+v))
const x=(i:number)=>40+i*48
// One unit is one pixel in either layout, so thickness never changes with baseline.
const y=(v:number)=>baseline.value==='centered'?110-v:170-v
function band(low:number[],high:number[]){return high.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ')+low.map((_,j)=>{const i=5-j;return ` L${x(i)},${y(low[i])}`}).join('')+' Z'}
const alphaPath=computed(()=>band(lower.value,middle.value)), betaPath=computed(()=>band(middle.value,upper.value))
function reset(){dataset.value='A';baseline.value='centered';selected.value=0;state.value='ready'}
</script>
<template>
<section class="stream-demo" aria-label="Local stream chart example"><p>Synthetic monthly units. Band thickness encodes each category. Centered position is not a negative value.</p><div class="stream-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option></select></label><label>Baseline<select v-model="baseline"><option value="centered">Centered stream</option><option value="zero">Zero-based stack</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><p class="stream-legend">Solid edge: Alpha · dashed edge: Beta. {{ baseline==='centered'?'Centered at a moving lower edge; read thickness, not height from zero.':'Stack starts at zero; top height equals the total.' }}</p><svg :key="dataset+'-'+baseline" viewBox="0 0 320 210" role="img" aria-label="Two synthetic categories, January to June. Read band thickness; exact values and totals are in the table below."><line x1="36" x2="292" :y1="y(0)" :y2="y(0)" class="stream-zero"/><text x="5" :y="y(0)+4">{{ baseline==='centered'?'center':'0' }}</text><path :d="alphaPath" class="stream-alpha"/><path :d="betaPath" class="stream-beta"/><line :x1="x(selected)" :x2="x(selected)" :y1="y(upper[selected])" :y2="y(lower[selected])" class="stream-selection"/><text v-for="(label,i) in labels" :key="label" :x="x(i)" y="194" text-anchor="middle">{{ label }}</text></svg><div role="group" aria-label="Select month" class="stream-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Alpha {{ alpha[selected] }}, Beta {{ beta[selected] }}, Total {{ totals[selected] }} units.</p><table class="stream-data"><caption>Exact units, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col">Alpha</th><th scope="col">Beta</th><th scope="col">Total</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ alpha[i] }}</td><td>{{ beta[i] }}</td><td>{{ totals[i] }}</td></tr></tbody></table></template><p v-else role="status" class="stream-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.stream-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.stream-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.stream-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.stream-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1);max-width:100%}.stream-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.stream-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.stream-legend{font-size:12px}.stream-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:stream-in .2s ease-out}.stream-demo svg text{fill:var(--vp-c-text-2);font-size:9px}.stream-zero{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.stream-alpha{fill:var(--vp-c-brand-1);fill-opacity:.25;stroke:var(--vp-c-brand-1);stroke-width:1.5}.stream-beta{fill:var(--vp-c-text-2);fill-opacity:.16;stroke:var(--vp-c-text-2);stroke-width:1.5;stroke-dasharray:5 3}.stream-selection{stroke:var(--vp-c-text-1);stroke-width:2}.stream-months{display:flex;gap:6px;flex-wrap:wrap}.stream-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.stream-data{display:table!important;width:100%;font-size:12px}.stream-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.stream-data :is(td,th){padding:6px!important}.stream-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes stream-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.stream-demo svg{animation:none}}
</style>
